import { existsSync, readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

// Browser icons generated by scripts/generate-favicons.mjs from the vector
// sources in scripts/. Next.js serves them through file-based metadata.
const repo = path.resolve(__dirname, "..", "..");
const appDir = path.join(repo, "src", "app");
const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const PALETTE = ["#292d63", "#f1f2f6", "#f99748", "#fff3e8"];

function png(buffer: Buffer) {
  expect(buffer.subarray(0, 8).equals(PNG_SIGNATURE)).toBe(true);
  return {
    width: buffer.readUInt32BE(16),
    height: buffer.readUInt32BE(20),
    colorType: buffer[25],
  };
}

function filesUnder(dir: string): string[] {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) =>
    entry.isDirectory()
      ? filesUnder(path.join(dir, entry.name))
      : [path.join(dir, entry.name)],
  );
}

describe("favicon assets", () => {
  it("favicon.ico holds 16, 32 and 48 px PNG frames", () => {
    const ico = readFileSync(path.join(appDir, "favicon.ico"));
    expect(ico.readUInt16LE(0)).toBe(0);
    expect(ico.readUInt16LE(2)).toBe(1);
    const count = ico.readUInt16LE(4);
    const sizes = Array.from({ length: count }, (_, index) => {
      const entry = 6 + 16 * index;
      const size = ico[entry];
      const length = ico.readUInt32LE(entry + 8);
      const offset = ico.readUInt32LE(entry + 12);
      expect(ico[entry + 1]).toBe(size);
      expect(ico.readUInt16LE(entry + 6)).toBe(32);
      expect(offset + length).toBeLessThanOrEqual(ico.length);
      const frame = png(ico.subarray(offset, offset + length));
      expect([frame.width, frame.height]).toEqual([size, size]);
      return size;
    });
    expect(sizes).toEqual([16, 32, 48]);
  });

  it("apple-icon.png is an opaque 180 px PNG", () => {
    const icon = png(readFileSync(path.join(appDir, "apple-icon.png")));
    expect([icon.width, icon.height]).toEqual([180, 180]);
    // Color type 2 = RGB without alpha: iOS applies its own rounded mask.
    expect(icon.colorType).toBe(2);
  });

  it("declares the icons once, only through the app root", () => {
    const iconFiles = filesUnder(appDir)
      .map((file) => path.relative(appDir, file))
      .filter((file) => /^(favicon|icon|apple-icon)\d*\.[a-z]+$/.test(path.basename(file)));
    expect(iconFiles.sort()).toEqual(["apple-icon.png", "favicon.ico"]);
    const publicIcons = readdirSync(path.join(repo, "public")).filter((file) =>
      /favicon|icon/i.test(file),
    );
    expect(publicIcons).toEqual([]);
    const sources = filesUnder(appDir).filter((file) => /\.(ts|tsx)$/.test(file) && !file.endsWith(".test.ts"));
    for (const file of sources) {
      expect(readFileSync(file, "utf8"), file).not.toMatch(/\bicons\s*:/);
    }
  });

  it.each(["favicon.svg", "favicon-16.svg"])(
    "keeps %s a clean, flat vector source",
    (name) => {
      const svg = readFileSync(path.join(repo, "scripts", name), "utf8");
      const viewBox = svg.match(/viewBox="([^"]+)"/)?.[1].split(" ").map(Number);
      expect(viewBox?.[2]).toBe(viewBox?.[3]);
      const elements = [...svg.matchAll(/<([a-zA-Z]+)[\s>]/g)].map((match) => match[1]);
      const allowed = ["svg", "rect", "path", "g", "circle"];
      expect(elements.filter((element) => !allowed.includes(element))).toEqual([]);
      expect(svg).not.toMatch(/<(script|image|text|style|foreignObject|linearGradient|radialGradient|filter)\b|href=|url\(|font/i);
      const colors = new Set(svg.match(/#[0-9a-f]{6}/gi)?.map((color) => color.toLowerCase()));
      expect([...colors].every((color) => PALETTE.includes(color))).toBe(true);
    },
  );
});
